blocks.text:
ping example.com          # RTT (지연)
traceroute example.com    # 거쳐 가는 라우터들 (윈도우: tracert)
curl -w '@-' -o /dev/null -s https://example.com <<'EOF'
  dns:    %{time_namelookup}
  tcp:    %{time_connect}
  tls:    %{time_appconnect}
  첫바이트: %{time_starttransfer}
  전체:   %{time_total}

EOF

const [nav] = performance.getEntriesByType('navigation');
console.log({
  dns:  nav.domainLookupEnd - nav.domainLookupStart,
  tcp:  nav.connectEnd - nav.connectStart,
  ttfb: nav.responseStart - nav.requestStart,   // 서버 처리 + 왕복
  body: nav.responseEnd - nav.responseStart,    // 본문 받기
});

